// Generated by Copilot — patched to handle >1000 rows via automatic pagination.

import { Student } from '../../types';
import { supabase } from '../supabase';

const MAX_QUERY_LIMIT = 10_000;
const PAGE_SIZE = 1000;

/**
 * Fetch all rows for a query that may exceed PostgREST's default 1000-row
 * limit. The caller provides a function that builds a fresh query (with any
 * filters) given a from/to range. Results are accumulated until a page
 * returns fewer rows than requested or the effective limit is reached.
 */
async function fetchAllPaginated<T>(
  buildQuery: (from: number, to: number) => any,
  effectiveLimit: number,
): Promise<T[]> {
  const all: T[] = [];
  let from = 0;
  while (true) {
    const remaining = effectiveLimit - all.length;
    if (remaining <= 0) break;
    const pageSize = Math.min(PAGE_SIZE, remaining);
    const to = from + pageSize - 1;
    const query = buildQuery(from, to);
    const { data, error } = await query;
    if (error) throw error;
    const rows = (data || []) as T[];
    all.push(...rows);
    if (rows.length < pageSize) break;
    from += pageSize;
  }
  return all;
}

function applyLimit(query: any, limit: number) {
  if (typeof query.limit === 'function') {
    return query.limit(Math.min(limit, MAX_QUERY_LIMIT));
  }
  return query;
}

export async function getStudents(limit: number = MAX_QUERY_LIMIT): Promise<Student[]> {
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  return fetchAllPaginated<Student>(
    (from, to) =>
      supabase
        .from('students')
        .select('id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId')
        .order('id', { ascending: true })
        .range(from, to),
    effectiveLimit,
  );
}

export async function getStudentsPaginated(page: number = 1, limit: number = 50, search?: string): Promise<{ students: Student[]; total: number }> {
  const from = (page - 1) * limit;
  const to = from + limit - 1;

  let query = supabase
    .from('students')
    .select('*', { count: 'exact' });

  if (search && search.trim()) {
    query = query.ilike('name', `%${search}%`);
  }

  const { data, error, count } = await query.range(from, to);
  if (error) throw error;
  return { students: (data || []) as Student[], total: count || 0 };
}

export async function getStudentById(id: string): Promise<Student | undefined> {
  const { data, error } = await supabase
    .from('students')
    .select('id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId')
    .eq('id', id)
    .single();
  if (error) return undefined;
  return data as Student | undefined;
}

export async function getStudentsByParent(parentId: string): Promise<Student[]> {
  const effectiveLimit = MAX_QUERY_LIMIT;
  return fetchAllPaginated<Student>(
    (from, to) =>
      supabase
        .from('students')
        .select('id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId')
        .eq('parentId', parentId)
        .order('id', { ascending: true })
        .range(from, to),
    effectiveLimit,
  );
}

export async function getStudentsByClass(className: string, limit: number = 100): Promise<Student[]> {
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  // For small limits (UI lists) a single range query is enough, but we still
  // paginate when the requested limit exceeds PAGE_SIZE so a class with >1000
  // students is not silently truncated.
  if (effectiveLimit <= PAGE_SIZE) {
    const { data, error } = await supabase
      .from('students')
      .select('id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId')
      .eq('className', className)
      .order('id', { ascending: true })
      .range(0, effectiveLimit - 1);
    if (error) throw error;
    return (data || []) as Student[];
  }
  return fetchAllPaginated<Student>(
    (from, to) =>
      supabase
        .from('students')
        .select('id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId')
        .eq('className', className)
        .order('id', { ascending: true })
        .range(from, to),
    effectiveLimit,
  );
}

export async function getStudentsByIds(ids: string[], limit: number = MAX_QUERY_LIMIT): Promise<Student[]> {
  if (!Array.isArray(ids) || ids.length === 0) return [];
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  // Supabase .in() with thousands of values can hit URL length limits; chunk
  // the ids and fetch each chunk with pagination.
  const uniqueIds = Array.from(new Set(ids));
  const chunks: string[][] = [];
  for (let i = 0; i < uniqueIds.length; i += PAGE_SIZE) {
    chunks.push(uniqueIds.slice(i, i + PAGE_SIZE));
  }
  const all: Student[] = [];
  for (const chunk of chunks) {
    if (all.length >= effectiveLimit) break;
    const remaining = effectiveLimit - all.length;
    // Each chunk is at most PAGE_SIZE, so a single range query suffices, but
    // we still paginate defensively.
    const fetched = await fetchAllPaginated<Student>(
      (from, to) =>
        supabase
          .from('students')
          .select('id,name,className,parentId,createdAt,govId,transport,parentPhone,familyId')
          .in('id', chunk)
          .order('id', { ascending: true })
          .range(from, to),
      Math.min(remaining, chunk.length),
    );
    all.push(...fetched);
  }
  // Deduplicate by id in case of overlapping chunks (should not happen).
  const seen = new Set<string>();
  const deduped: Student[] = [];
  for (const s of all) {
    if (!seen.has(s.id)) {
      seen.add(s.id);
      deduped.push(s);
    }
  }
  return deduped.slice(0, effectiveLimit);
}

export async function getStudentsByClasses(classnames: string[], search?: string, limit: number = MAX_QUERY_LIMIT): Promise<Student[]> {
  // Default was historically 1000, which accidentally truncated rosters with
  // >1000 students. We now treat the limit as a maximum but fetch all pages
  // up to that maximum, so a request for 1000 still returns up to 1000, but
  // a request for 10_000 correctly returns up to 10_000 via pagination.
  const effectiveLimit = Math.min(limit, MAX_QUERY_LIMIT);
  if (effectiveLimit <= PAGE_SIZE) {
    // Fast path for small limits — single query.
    let query = supabase
      .from('students')
      .select('id,name,className,parentId,govId,transport,parentPhone,familyId')
      .order('id', { ascending: true });
    if (classnames && classnames.length > 0) {
      query = query.in('className', classnames);
    }
    if (search && search.trim()) {
      query = query.ilike('name', `%${search}%`);
    }
    const { data, error } = await query.range(0, effectiveLimit - 1);
    if (error) throw error;
    return (data || []) as Student[];
  }
  return fetchAllPaginated<Student>(
    (from, to) => {
      let q: any = supabase.from('students').select('id,name,className,parentId,govId,transport,parentPhone,familyId');
      if (classnames && classnames.length > 0) {
        q = q.in('className', classnames);
      }
      if (search && search.trim()) {
        q = q.ilike('name', `%${search}%`);
      }
      return q.order('id', { ascending: true }).range(from, to);
    },
    effectiveLimit,
  );
}

export async function getStudentIdsByClasses(classnames: string[]): Promise<string[]> {
  if (!classnames || classnames.length === 0) return [];
  const students = await getStudentsByClasses(classnames, undefined, MAX_QUERY_LIMIT);
  return students.map(student => student.id);
}

export async function getStudentClasses(): Promise<string[]> {
  const effectiveLimit = MAX_QUERY_LIMIT;
  const rows = await fetchAllPaginated<{ className?: string }>(
    (from, to) =>
      supabase.from('students').select('className').order('className', { ascending: true }).range(from, to),
    effectiveLimit,
  );
  const classes = Array.from(new Set(rows.map(r => r.className).filter(Boolean)));
  classes.sort();
  return classes as string[];
}

/**
 * Student mutations go through admin-gated SECURITY DEFINER RPCs. There is no
 * client INSERT/UPDATE/DELETE policy on `students` (RLS is SELECT-only); these
 * wrappers preserve the previous call signatures while enforcing the server
 * role check, audit trail, and enrollment-history maintenance.
 */
export async function createStudent(data: Omit<Student, 'id' | 'createdAt'>): Promise<Student> {
  const { data: created, error } = await supabase.rpc('create_student', {
    p_name: data.name,
    p_class: data.className,
    p_parent_id: data.parentId ?? null,
    p_gov_id: data.govId ?? null,
    p_parent_phone: data.parentPhone ?? null,
  });
  if (error) {
    console.error('Error creating student:', error);
    throw new Error(error.message);
  }
  return {
    id: (created as any)?.id,
    name: (created as any)?.name ?? data.name,
    className: (created as any)?.className ?? data.className,
    parentId: data.parentId ?? null,
    govId: data.govId ?? null,
    parentPhone: data.parentPhone ?? null,
    createdAt: new Date().toISOString(),
  } as Student;
}

/**
 * update_student() (20260906c_student_write_security.sql) uses NULL as the
 * "leave this column alone" sentinel for every optional argument, and applies
 * NULLIF(p_parent_id,'') when it does write. So:
 *   * omit the key entirely            -> NULL  -> column untouched
 *   * pass a parent id                 -> that id is assigned
 *   * pass null (explicit unassign)    -> '' -> the RPC stores NULL
 * Sending raw null for an explicit unassign (the previous behaviour) was
 * silently a no-op: administrators could never REMOVE a wrongly assigned
 * parent from a student.
 */
function rpcNullable(value: string | null | undefined): string | null {
  if (value === undefined) return null; // no change
  return value ?? '';                   // '' => explicit clear inside the RPC
}

export async function updateStudent(id: string, data: Partial<Student>): Promise<Student | null> {
  const { error } = await supabase.rpc('update_student', {
    p_student_id: id,
    p_name: data.name ?? null,
    p_class: data.className ?? null,
    p_parent_id: rpcNullable(data.parentId),
    p_gov_id: rpcNullable(data.govId),
    p_parent_phone: rpcNullable(data.parentPhone),
    p_transport: rpcNullable(data.transport),
  });
  if (error) {
    console.error('Error updating student:', error);
    throw new Error(error.message);
  }
  return (await getStudentById(id)) ?? null;
}

export async function deleteStudent(id: string): Promise<boolean> {
  const { error } = await supabase.rpc('delete_student', { p_student_id: id });
  if (error) {
    console.error('Error deleting student:', error);
    return false;
  }
  // Grades/attendance/homework cascade via FK ON DELETE inside the transaction.
  return true;
}

export async function promoteStudentsByClass(
  fromClass: string,
  toClass: string,
  academicYearId?: string
): Promise<number> {
  const { data, error } = await supabase.rpc('promote_students', {
    from_class: fromClass,
    to_class: toClass,
    academic_year_id: academicYearId ?? null,
  });
  if (error) throw new Error(error.message);
  return Array.isArray(data) ? data.length : 0;
}
